#!/usr/bin/env python3
# Usage: scratch_litgaps_osflic.py OSFID [...]  -> licence of node and its child components (metadata only)
import sys, json, urllib.request
def get(u):
    return json.load(urllib.request.urlopen(u, timeout=30))
lic_cache={}
def licname(d):
    rel=(d["relationships"].get("license",{}) or {}).get("data")
    if not rel: return "NONE"
    i=rel["id"]
    if i not in lic_cache: lic_cache[i]=get(f"https://api.osf.io/v2/licenses/{i}/")["data"]["attributes"]["name"]
    return lic_cache[i]
def walk(nid, depth=0):
    try: d=get(f"https://api.osf.io/v2/nodes/{nid}/")["data"]
    except Exception as e: print("  "*depth+f"{nid}: ERROR {e}"); return
    print("  "*depth+f"{nid}: {d['attributes']['title'][:70]} | {licname(d)}")
    if depth<2:
        try:
            for c in get(f"https://api.osf.io/v2/nodes/{nid}/children/")["data"]: walk(c["id"], depth+1)
        except Exception: pass
for n in sys.argv[1:]: walk(n)
EOF
